function community_schema(PDO $db):void{
 $db->exec("CREATE TABLE IF NOT EXISTS communities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT NULL,category VARCHAR(80) NOT NULL DEFAULT 'General',location_name VARCHAR(160) NOT NULL DEFAULT '',privacy ENUM('public','private') NOT NULL DEFAULT 'public',join_policy ENUM('anyone','approval') NOT NULL DEFAULT 'anyone',post_permission ENUM('all','approved','staff') NOT NULL DEFAULT 'all',post_approval ENUM('immediate','approval') NOT NULL DEFAULT 'immediate',profile_image VARCHAR(500) NOT NULL DEFAULT '',cover_image VARCHAR(500) NOT NULL DEFAULT '',status TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY(owner_user_id),KEY(category,status),KEY(location_name,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $column=$db->query("SHOW COLUMNS FROM communities LIKE 'location_name'")->fetch(PDO::FETCH_ASSOC);
 if(!$column)$db->exec("ALTER TABLE communities ADD location_name VARCHAR(160) NOT NULL DEFAULT '' AFTER category, ADD KEY(location_name,status)");
 $db->exec("CREATE TABLE IF NOT EXISTS community_members(community_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,role ENUM('owner','admin','moderator','manager','member') NOT NULL DEFAULT 'member',status ENUM('active','pending','suspended','blocked') NOT NULL DEFAULT 'active',joined_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(community_id,user_id),KEY(user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 try{$roleColumn=$db->query("SHOW COLUMNS FROM community_members LIKE 'role'")->fetch(PDO::FETCH_ASSOC);if($roleColumn&&stripos((string)($roleColumn['Type']??''),"'manager'")===false)$db->exec("ALTER TABLE community_members MODIFY role ENUM('owner','admin','moderator','manager','member') NOT NULL DEFAULT 'member'");}catch(Throwable $eRole){}
 $db->exec("CREATE TABLE IF NOT EXISTS community_rules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,community_id BIGINT UNSIGNED NOT NULL,rule_text VARCHAR(280) NOT NULL,sort_order INT NOT NULL DEFAULT 0,KEY(community_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $db->exec("CREATE TABLE IF NOT EXISTS community_invitations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,community_id BIGINT UNSIGNED NOT NULL,invited_user_id BIGINT UNSIGNED NOT NULL,invited_by_user_id BIGINT UNSIGNED NOT NULL,status ENUM('pending','accepted','declined','cancelled') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,responded_at DATETIME NULL,KEY(invited_user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
}
function community_image(string $field,int $uid):string{
 if(empty($_FILES[$field])||(int)($_FILES[$field]['error']??99)!==UPLOAD_ERR_OK)return'';
 $tmp=(string)$_FILES[$field]['tmp_name']; $info=@getimagesize($tmp); if(!is_uploaded_file($tmp)||$info===false)return'';
 $mime=(string)(mime_content_type($tmp)?:($info['mime']??''));$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'][$mime]??'';if($ext==='')return'';
 $dir=__DIR__.'/uploads/communities';if(!is_dir($dir))@mkdir($dir,0775,true);$name='community_'.$uid.'_'.bin2hex(random_bytes(8)).'.'.$ext;
 return @move_uploaded_file($tmp,$dir.'/'.$name)?'uploads/communities/'.$name:'';
}
try{community_schema($dbh);}catch(Throwable $e){}
if(empty($_SESSION['community_csrf']))$_SESSION['community_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['community_csrf'];$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Your session changed. Please try again.');
  $action=(string)($_POST['community_action']??'');$cid=(int)($_POST['community_id']??0);
  if($action==='create'){
   $name=mb_substr(trim((string)($_POST['name']??'')),0,150);if($name==='')throw new RuntimeException('Enter a community name.');
   $location=mb_substr(trim((string)($_POST['location_name']??'')),0,160);if($location==='')throw new RuntimeException('Enter the city and state for this community.');
   $privacy=(string)($_POST['privacy']??'')==='private'?'private':'public';$join=(string)($_POST['join_policy']??'')==='approval'?'approval':'anyone';
   $posting=in_array((string)($_POST['post_permission']??''),['all','approved','staff'],true)?(string)$_POST['post_permission']:'all';$approval=(string)($_POST['post_approval']??'')==='approval'?'approval':'immediate';
   $dbh->beginTransaction();$st=$dbh->prepare('INSERT INTO communities(owner_user_id,name,description,category,location_name,privacy,join_policy,post_permission,post_approval,profile_image,cover_image)VALUES(:o,:n,:d,:c,:l,:p,:j,:pp,:pa,:pi,:ci)');
   $st->execute([':o'=>$meId,':n'=>$name,':d'=>mb_substr(trim((string)($_POST['description']??'')),0,3000),':c'=>mb_substr(trim((string)($_POST['category']??'Local Support')),0,80),':l'=>$location,':p'=>$privacy,':j'=>$join,':pp'=>$posting,':pa'=>$approval,':pi'=>community_image('profile_image',$meId),':ci'=>community_image('cover_image',$meId)]);$cid=(int)$dbh->lastInsertId();
   $dbh->prepare("INSERT INTO community_members(community_id,user_id,role,status,joined_at,created_at,updated_at)VALUES(:c,:u,'owner','active',NOW(),NOW(),NOW())")->execute([':c'=>$cid,':u'=>$meId]);$rs=$dbh->prepare('INSERT INTO community_rules(community_id,rule_text,sort_order)VALUES(:c,:r,:s)');
   foreach(array_slice(array_values(array_filter(array_map('trim',(array)($_POST['rules']??[])))),0,10)as$i=>$rule)$rs->execute([':c'=>$cid,':r'=>mb_substr($rule,0,280),':s'=>$i]);$dbh->commit();header('Location: community.php?tab=my&created=1');exit;
  }
  if($cid<=0)throw new RuntimeException('Community not found.');
  if($action==='join'){$st=$dbh->prepare('SELECT join_policy,owner_user_id FROM communities WHERE id=:c AND status=1');$st->execute([':c'=>$cid]);$crow=$st->fetch(PDO::FETCH_ASSOC)?:[];$pending=((string)($crow['join_policy']??''))==='approval';$ownerId=(int)($crow['owner_user_id']??0);$status=$pending?'pending':'active';$joined=$pending?null:date('Y-m-d H:i:s');$dbh->prepare("INSERT INTO community_members(community_id,user_id,role,status,joined_at)VALUES(:c,:u,'member',:s,:j)ON DUPLICATE KEY UPDATE status=VALUES(status),joined_at=VALUES(joined_at)")->execute([':c'=>$cid,':u'=>$meId,':s'=>$status,':j'=>$joined]);require_once __DIR__.'/includes/community_invite_notify.php';community_notify_member_joined($dbh,$meId,$ownerId,$cid,(bool)$pending);$notice=$pending?'Your request was sent.':'You joined the community.';}
  elseif($action==='leave'){$ownerId=0;try{$stO=$dbh->prepare('SELECT owner_user_id FROM communities WHERE id=:c LIMIT 1');$stO->execute([':c'=>$cid]);$ownerId=(int)($stO->fetchColumn()?:0);}catch(Throwable $eO){}$dbh->prepare("DELETE FROM community_members WHERE community_id=:c AND user_id=:u AND role<>'owner'")->execute([':c'=>$cid,':u'=>$meId]);require_once __DIR__.'/includes/community_invite_notify.php';community_notify_member_left($dbh,$meId,$ownerId,$cid);$notice='You left the community.';}
  elseif(in_array($action,['accept_invite','decline_invite'],true)){$iid=(int)($_POST['invite_id']??0);if($iid<=0)throw new RuntimeException('Missing invitation.');$stInv=$dbh->prepare("SELECT id,community_id,invited_by_user_id FROM community_invitations WHERE id=:i AND invited_user_id=:u AND status='pending' LIMIT 1");$stInv->execute([':i'=>$iid,':u'=>$meId]);$invRow=$stInv->fetch(PDO::FETCH_ASSOC);if(!$invRow)throw new RuntimeException('Invitation not found or already answered.');$inviteCommunityId=(int)$invRow['community_id'];$inviterUserId=(int)($invRow['invited_by_user_id']??0);$accepted=$action==='accept_invite';$dbh->prepare("UPDATE community_invitations SET status=:s,responded_at=NOW() WHERE community_id=:c AND invited_user_id=:u AND status='pending'")->execute([':s'=>$accepted?'accepted':'declined',':c'=>$inviteCommunityId,':u'=>$meId]);if($accepted){$dbh->prepare("INSERT INTO community_members(community_id,user_id,role,status,joined_at)VALUES(:c,:u,'member','active',NOW())ON DUPLICATE KEY UPDATE status='active',joined_at=NOW()")->execute([':c'=>$inviteCommunityId,':u'=>$meId]);}require_once __DIR__.'/includes/community_invite_notify.php';community_notify_invite_response($dbh,$meId,$inviterUserId,$inviteCommunityId,$accepted);if($accepted){$notice='Invitation accepted. You joined the community.';header('Location: community_profile.php?id='.$inviteCommunityId);exit;}else{$notice='Invitation declined.';}}
 }catch(Throwable $e){if($dbh->inTransaction())$dbh->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Unable to update the community right now.';}
}
$tab=strtolower(trim((string)($_GET['tab']??'discover')));if(!in_array($tab,['discover','my','joined','invitations'],true))$tab='discover';$q=trim((string)($_GET['q']??''));$location=trim((string)($_GET['location']??''));$cats=['All','Emotional Support','Local Events','Church & Faith','Make New Friends','Local Advertising','Travel','Photography','Nearby Stores','Food','Education','Pets','Arts & Culture'];$category=trim((string)($_GET['category']??'All'));
$rows=[];$invites=[];$select="SELECT c.*,COALESCE(NULLIF(u.name,''),u.username,'Community Owner')owner_name,(SELECT COUNT(*)FROM community_members x WHERE x.community_id=c.id AND x.status='active')member_count,m.role my_role,m.status my_status FROM communities c JOIN users u ON u.id=c.owner_user_id LEFT JOIN community_members m ON m.community_id=c.id AND m.user_id=:me";$params=[':me'=>$meId];$where=' WHERE c.status=1';
if($tab==='discover')$where.=" AND(m.user_id IS NULL OR m.status<>'active')";elseif($tab==='my')$where.=" AND m.status='active' AND m.role IN('owner','admin','moderator','manager')";elseif($tab==='joined')$where.=" AND m.status='active' AND m.role='member'";if($q!==''){$where.=' AND(c.name LIKE :q OR c.description LIKE :q OR c.category LIKE :q)';$params[':q']='%'.$q.'%';}if($location!==''){$where.=' AND c.location_name LIKE :location';$params[':location']='%'.$location.'%';}if(strcasecmp($category,'All')!==0){$where.=' AND c.category=:cat';$params[':cat']=$category;}
try{if($tab!=='invitations'){$st=$dbh->prepare($select.$where.' ORDER BY c.updated_at DESC LIMIT 100');$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}else{$focusInvite=(int)($_GET['invite']??0);$st=$dbh->prepare("SELECT i.id invite_id,c.*,(SELECT COUNT(*)FROM community_members x WHERE x.community_id=c.id AND x.status='active')member_count FROM community_invitations i JOIN communities c ON c.id=i.community_id WHERE i.invited_user_id=:me AND i.status='pending' AND c.status=1 ORDER BY i.created_at DESC");$st->execute([':me'=>$meId]);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];if($focusInvite>0&&$rows){usort($rows,static function($a,$b)use($focusInvite){$aid=(int)($a['invite_id']??0)===$focusInvite?0:1;$bid=(int)($b['invite_id']??0)===$focusInvite?0:1;return $aid<=>$bid;});}}}catch(Throwable $e){}
?>
