<?php if($tab==='discover'):?><nav class="cats"><?php foreach($cats as$c):?><a class="cat<?=strcasecmp($category,$c)===0?' active':''?>" href="community.php?tab=discover&amp;category=<?=rawurlencode($c)?>&amp;location=<?=rawurlencode($location)?>"><?=h($c)?></a><?php endforeach;?></nav><?php endif;?>
<?php if((string)($_GET['created']??'')==='1'||$notice!==''):?><div class="alert"><?=h($notice!==''?$notice:'Community created. You are now its Owner.')?></div><?php endif;?><?php if($error!==''):?><div class="alert error"><?=h($error)?></div><?php endif;?><?php if($tab==='invitations'&&(int)($_GET['invite']??0)>0):?><div class="invite-banner">You have a community invitation. Accept to join, or Decline if you are not interested.</div><?php endif;?>
<?php if($rows):?><section class="grid"><?php $focusInvite=(int)($_GET['invite']??0);foreach($rows as$r):$cid=(int)$r['id'];$cover=trim((string)($r['cover_image']??''));$isFocus=$focusInvite>0&&(int)($r['invite_id']??0)===$focusInvite;?><article class="card<?=$isFocus?' is-invite-focus':''?>"<?=$isFocus?' id="community-invite-focus"':''?>><a class="cover" href="community_profile.php?id=<?=$cid?>"<?=$cover!==''?' style="background-image:url(\''.h($cover).'\')"':''?>></a><div class="body"><a class="title" href="community_profile.php?id=<?=$cid?>"><?=h((string)$r['name'])?></a><span class="meta"><?=(int)($r['member_count']??0)?> members · <?=h(ucfirst((string)$r['privacy']))?></span><span class="location"><i class="fa fa-map-marker"></i> <?=h((string)($r['location_name']??'Local community'))?></span><p class="desc"><?=h((string)($r['description']??''))?></p><div class="actions">
<?php if($tab==='discover'):?><?php if(($r['my_status']??'')==='pending'):?><button class="action" type="button" disabled>Requested</button><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="community_id" value="<?=$cid?>"><button class="action primary" name="community_action" value="join"><?=($r['join_policy']??'')==='approval'?'Request to Join':'Join'?></button></form><?php endif;?><?php elseif($tab==='invitations'):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="community_id" value="<?=$cid?>"><input type="hidden" name="invite_id" value="<?=(int)$r['invite_id']?>"><button class="action primary" name="community_action" value="accept_invite">Accept</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="community_id" value="<?=$cid?>"><input type="hidden" name="invite_id" value="<?=(int)$r['invite_id']?>"><button class="action" name="community_action" value="decline_invite">Decline</button></form><?php else:?><a class="action primary" href="community_profile.php?id=<?=$cid?>">View Community</a><?php if(($r['my_role']??'')==='member'):?><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="community_id" value="<?=$cid?>"><button class="action" name="community_action" value="leave">Leave</button></form><?php else:?><a class="action" href="community_profile.php?id=<?=$cid?>#manage">Manage</a><?php endif;?><?php endif;?></div></div></article><?php endforeach;?></section><?php else:?><div class="empty"><?=$tab==='discover'?'No new communities match this view yet.':($tab==='invitations'?'You have no pending community invitations.':'No communities appear here yet.')?></div><?php endif;?></div></main>
<div class="modal" id="createModal" hidden><form class="dialog" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="community_action" value="create"><header class="dialog-head"><h2>Create Community</h2><button class="close" type="button">&times;</button></header><div class="steps"><?php for($i=1;$i<=5;$i++):?><span class="dot<?=$i===1?' active':''?>"></span><?php endfor;?></div>
<section class="pane" data-step="1"><h3>Basic information</h3><label class="field"><span>Community Name</span><input name="name" maxlength="150" required placeholder="Garland Neighbors & Support"></label><label class="field"><span>City and state</span><input name="location_name" maxlength="160" required placeholder="Garland, TX"></label><label class="field"><span>Description</span><textarea name="description" rows="4" placeholder="Explain how this local community helps people connect and support one another."></textarea></label><label class="field"><span>Purpose</span><select name="category"><?php foreach(array_slice($cats,1)as$c):?><option><?=h($c)?></option><?php endforeach;?><option>Other Local Interest</option></select></label><div class="choices"><label><input type="radio" name="privacy" value="public" checked> 🌎 Public</label><label><input type="radio" name="privacy" value="private"> 🔒 Private</label></div></section>
<section class="pane" data-step="2" hidden><h3>Appearance</h3><label class="field"><span>Community profile image/logo</span><input type="file" name="profile_image" accept="image/*"></label><label class="field"><span>Cover image</span><input type="file" name="cover_image" accept="image/*"></label></section>
<section class="pane" data-step="3" hidden><h3>Membership and posting</h3><label class="field"><span>Who can join?</span><select name="join_policy"><option value="anyone">Anyone</option><option value="approval">Admin approval required</option></select></label><label class="field"><span>Who can post?</span><select name="post_permission"><option value="all">All members</option><option value="approved">Approved members</option><option value="staff">Admins/Moderators only</option></select></label><label class="field"><span>Post approval</span><select name="post_approval"><option value="immediate">Publish immediately</option><option value="approval">Require moderator approval</option></select></label></section>
<section class="pane" data-step="4" hidden><h3>Community Rules</h3><div class="rules"><?php foreach(['Be respectful','No spam','Stay on topic','No harassment','No misleading information']as$rule):?><input class="field" name="rules[]" value="<?=h($rule)?>" maxlength="280"><?php endforeach;?></div></section><section class="pane" data-step="5" hidden><h3>Preview & Create</h3><p>You will automatically become the Owner. The community will appear under My Communities.</p></section><footer class="wizard-actions"><button class="back" type="button" hidden>Back</button><button class="next" type="button">Continue</button><button class="submit" type="submit" hidden>Create Community</button></footer></form></div>
<script>(function(){var m=document.getElementById('createModal'),o=document.getElementById('openCreate'),x=m.querySelector('.close'),n=m.querySelector('.next'),b=m.querySelector('.back'),s=m.querySelector('.submit'),p=[].slice.call(m.querySelectorAll('.pane')),d=[].slice.call(m.querySelectorAll('.dot')),i=1;function paint(){p.forEach(function(e,k){e.hidden=k!==i-1});d.forEach(function(e,k){e.classList.toggle('active',k<i)});b.hidden=i===1;n.hidden=i===5;s.hidden=i!==5}o.onclick=function(){m.hidden=false;i=1;paint()};x.onclick=function(){m.hidden=true};m.onclick=function(e){if(e.target===m)m.hidden=true};n.onclick=function(){var req=p[i-1].querySelectorAll('[required]');for(var k=0;k<req.length;k++)if(!req[k].reportValidity())return;i=Math.min(5,i+1);paint()};b.onclick=function(){i=Math.max(1,i-1);paint()};document.addEventListener('keydown',function(e){if(e.key==='Escape')m.hidden=true})})();</script><script>(function(){var el=document.getElementById("community-invite-focus");if(el){try{el.scrollIntoView({behavior:"smooth",block:"center"});}catch(e){el.scrollIntoView(true);}}})();</script></body></html>
